package kr.workbench;
import java.io.*;import javax.xml.XMLConstants;import javax.xml.parsers.*;import javax.xml.transform.*;import javax.xml.transform.dom.DOMSource;import javax.xml.transform.stream.StreamResult;
/** Display-only formatting: never edits stored or transmitted packets. */
public final class PacketFormat {
 public static String decodedResponse(burp.api.montoya.http.message.responses.HttpResponse value){if(value==null)return null;try{return response(value.toByteArray().getBytes(),value.statusCode(),"",JsAnalysisPanel.readBody(value));}catch(Exception e){return value.toString();}}
 public static String pretty(String packet){int split=packet.indexOf("\r\n\r\n"),sep=4;if(split<0){split=packet.indexOf("\n\n");sep=2;}if(split<0)return packet;String head=packet.substring(0,split),body=HttpText.display(packet.substring(split+sep)),trim=body.strip();if(body.length()>65536)return packet;
 try{String formatted=body;if(trim.startsWith("{")||trim.startsWith("[")){MinerJson.parse(trim);formatted=json(trim);}else if(trim.startsWith("<")&&!trim.toLowerCase(java.util.Locale.ROOT).contains("<!doctype html")&&!trim.toLowerCase(java.util.Locale.ROOT).contains("<html")){DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setXIncludeAware(false);f.setExpandEntityReferences(false);f.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");f.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");var b=f.newDocumentBuilder();b.setErrorHandler(new org.xml.sax.helpers.DefaultHandler());var document=b.parse(new org.xml.sax.InputSource(new StringReader(trim)));TransformerFactory tf=TransformerFactory.newInstance();tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD,"");tf.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET,"");var t=tf.newTransformer();t.setOutputProperty(OutputKeys.INDENT,"yes");t.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION,"yes");t.setOutputProperty("{http://xml.apache.org/xslt}indent-amount","2");StringWriter out=new StringWriter();t.transform(new DOMSource(document),new StreamResult(out));formatted=out.toString();}else if(trim.startsWith("<")){formatted=trim.replaceAll(">\\s*<",">\n<");}if(formatted.length()>131072)return packet;return head+"\n\n"+formatted;}catch(Exception e){return packet;}}
 public static String decode(byte[] bytes){try{return java.nio.charset.StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes)).toString();}catch(Exception e){return new String(bytes,java.nio.charset.StandardCharsets.ISO_8859_1);}}
 public static String response(byte[] raw,int status,String mime,String body){String wire=decode(raw);int end=wire.indexOf("\r\n\r\n");if(end<0)end=wire.indexOf("\n\n");String header=end>=0&&wire.startsWith("HTTP/")?wire.substring(0,end):"HTTP/1.1 "+status+"\r\nContent-Type: "+mime;return header+"\r\n\r\n"+body;}
 static String json(String s){StringBuilder b=new StringBuilder();boolean quoted=false,escape=false;int depth=0;for(int i=0;i<s.length();i++){char c=s.charAt(i);if(quoted){b.append(c);if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;continue;}if(c=='"'){quoted=true;b.append(c);}else if(c=='{'||c=='['){b.append(c);depth++;int j=i+1;while(j<s.length()&&Character.isWhitespace(s.charAt(j)))j++;if(j<s.length()&&s.charAt(j)!=(c=='{'?'}':']'))newline(b,depth);}else if(c=='}'||c==']'){depth--;int j=i-1;while(j>=0&&Character.isWhitespace(s.charAt(j)))j--;if(j>=0&&s.charAt(j)!='{'&&s.charAt(j)!='[')newline(b,depth);b.append(c);}else if(c==','){b.append(c);newline(b,depth);}else if(c==':')b.append(": ");else if(!Character.isWhitespace(c))b.append(c);}return b.toString();}
 static void newline(StringBuilder b,int depth){b.append('\n').append("  ".repeat(Math.max(0,depth)));}
}
